public class Utils {
	public static ResourceLocation parseResourceLocation(String id) {
		if (id.contains(":")) {
			return new ResourceLocation(id);
		}
		return new ResourceLocation(KubeJS.MOD_ID, id);
	}

	public static ResourceLocation asResourceLocation(Object o) {
		if (o instanceof ResourceLocation rl) {
			return rl;
		} else if (o instanceof String s) {
			return parseResourceLocation(s);
		}
		throw new IllegalArgumentException("Cannot convert " + o + " to ResourceLocation");
	}

	public static ItemStack toItemStack(Object o) {
		if (o instanceof ItemStack is) {
			return is;
		} else if (o instanceof String s) {
			return new ItemStack(Registry.ITEM.get(asResourceLocation(s)));
		}
		throw new IllegalArgumentException("Cannot convert " + o + " to ItemStack");
	}

	public static Ingredient toIngredient(Object o) {
		if (o instanceof Ingredient i) {
			return i;
		} else if (o instanceof ItemStack is) {
			return Ingredient.of(is);
		} else if (o instanceof String s) {
			return Ingredient.of(toItemStack(s));
		}
		throw new IllegalArgumentException("Cannot convert " + o + " to Ingredient");
	}
}
